if.script:
try {
    lastReadTimeStamp = java.sql.Timestamp.valueOf(
        lastReadPref.preferenceValue.toString().trim())
} catch (IllegalArgumentException e) {
    ec.logger.warn("Unusable notification-lastReadDate " +
        "[${lastReadPref.preferenceValue}] for user " +
        "${ec.user.userAccount.userId}, reading from the start")
}

else.script:
try {
    ec.transaction.runRequireNew(60, null, {
        ec.entity.makeValue("moqui.security.UserPreference")
            .setAll([userId: ec.user.userAccount.userId,
                preferenceKey: 'notification-lastReadDate',
                preferenceValue: nowTimestamp.toString()])
            .create()
    })
} catch (Throwable t) {
    ec.logger.info("notification-lastReadDate for user " +
        "${ec.user.userAccount.userId} was written by a concurrent " +
        "request: ${t.message}")
}
